#!/usr/bin/env node

// Needs the package.json generated by `mise build`.
const assert = require('assert');
const config = require('../src/pkjs/clay/config.js');
const clayI18n = require('../src/pkjs/clay/i18n.js');

/**
 * Collect every item that carries a messageKey.
 *
 * @param {Object[]} items Clay config items.
 * @param {Object[]} out Accumulator.
 * @returns {Object[]} Items with a messageKey.
 */
function keyedItems(items, out) {
  items.forEach(function(item) {
    if (item.messageKey) {
      out.push(item);
    }
    if (Array.isArray(item.items)) {
      keyedItems(item.items, out);
    }
  });
  return out;
}

const before = JSON.stringify(config);
const items = keyedItems(config, []);
const byKey = {};
items.forEach(function(item) {
  byKey[item.messageKey] = item;
});

Object.keys(clayI18n.TRANSLATIONS).forEach(function(language) {
  const dict = clayI18n.TRANSLATIONS[language];

  items.forEach(function(item) {
    if (item.label) {
      assert.ok(dict.items[item.messageKey] && dict.items[item.messageKey].label,
        language + ': missing label for ' + item.messageKey);
    }
  });

  Object.keys(dict.items).forEach(function(key) {
    assert.ok(byKey[key], language + ': translation for unknown messageKey ' + key);
    const options = dict.items[key].options || {};
    Object.keys(options).forEach(function(value) {
      assert.ok((byKey[key].options || []).some(function(option) {
        return String(option.value) === value;
      }), language + ': unknown option ' + key + '=' + value);
    });
  });

  const localized = clayI18n.localizeConfig(config, language);
  const localizedByKey = {};
  keyedItems(localized, []).forEach(function(item) {
    localizedByKey[item.messageKey] = item;
  });
  assert.strictEqual(localizedByKey.faceTheme.label, dict.items.faceTheme.label);
  assert.ok(localized.some(function(item) {
    return item.type === 'submit' && item.defaultValue === dict.text['Save Settings'];
  }), language + ': submit button not translated');
});

assert.deepStrictEqual(clayI18n.localizeConfig(config, 'en'), config);
assert.strictEqual(JSON.stringify(config), before);

assert.strictEqual(clayI18n.resolveLanguage('ru', { language: 'en_US' }, 'en-US'), 'ru');
assert.strictEqual(clayI18n.resolveLanguage('en', { language: 'ru_RU' }, 'ru-RU'), 'en');
assert.strictEqual(clayI18n.resolveLanguage('auto', { language: 'ru_RU' }, 'en-US'), 'ru');
assert.strictEqual(clayI18n.resolveLanguage('auto', null, 'ru-RU'), 'ru');
assert.strictEqual(clayI18n.resolveLanguage('auto', { language: 'de_DE' }, 'ru-RU'), 'en');
assert.strictEqual(clayI18n.resolveLanguage(undefined, null, null), 'en');
assert.deepStrictEqual(clayI18n.pageStrings('en'), {});

console.log('Clay i18n tests passed');
